"""Data engine module for synthetic/real-composited dataset generation."""

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Optional

from data_engine.camera import create_camera_backend
from data_engine.capture import BackgroundCaptureSession, CaptureConfig


@dataclass
class DataEngineConfig:
    output_dir: Path
    num_samples: int = 0
    seed: int = 0


class DataEngine:
    """Entry point for data generation workflows."""

    def __init__(self, config: DataEngineConfig) -> None:
        self.config = config
        self.config.output_dir.mkdir(parents=True, exist_ok=True)

    @staticmethod
    def load_json_config(path: Path) -> Dict[str, Any]:
        """Load a JSON config file."""
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)

    def capture_backgrounds(
        self,
        camera_config: Dict[str, Any],
        capture_config: Optional[Dict[str, Any]] = None,
    ) -> Path:
        """Run an interactive background capture session."""
        capture_config = capture_config or {}

        camera = create_camera_backend(camera_config)
        cap_cfg = CaptureConfig(
            output_root=Path(capture_config.get("output_root", self.config.output_dir / "backgrounds" / "raw")),
            session_name=capture_config.get("session_name"),
            max_frames=int(capture_config.get("max_frames", 0)),
            preview_max_depth_m=float(capture_config.get("preview_max_depth_m", 5.0)),
            save_preview_png=bool(capture_config.get("save_preview_png", True)),
        )
        session = BackgroundCaptureSession(camera=camera, config=cap_cfg)
        return session.run()

    def build_dataset(self) -> None:
        """Generate dataset assets and metadata."""
        raise NotImplementedError("Data generation is not implemented yet.")

"""Generic OpenCV backend.

This backend is intentionally simple and treats incoming single-channel or BGR
frames as depth-like input for quick prototyping with non-RealSense cameras.
"""

from __future__ import annotations

import importlib
import time
from typing import Any, Dict, Optional, Union

import numpy as np

from .base import DepthCameraBackend, DepthFrame


class OpenCVDepthBackend(DepthCameraBackend):
    """Generic backend using cv2.VideoCapture."""

    def __init__(
        self,
        source: Union[int, str] = 0,
        width: Optional[int] = None,
        height: Optional[int] = None,
        fps: Optional[int] = None,
        depth_scale: float = 1.0,
    ) -> None:
        self.source = source
        self.width = width
        self.height = height
        self.fps = fps
        self.depth_scale = float(depth_scale)
        self._cap = None
        self._cv2 = None

    def start(self) -> None:
        try:
            self._cv2 = importlib.import_module("cv2")
        except ImportError as exc:
            raise RuntimeError("opencv-python is required for OpenCV backend.") from exc

        self._cap = self._cv2.VideoCapture(self.source)
        if not self._cap.isOpened():
            raise RuntimeError(f"Failed to open camera source: {self.source}")

        if self.width is not None:
            self._cap.set(self._cv2.CAP_PROP_FRAME_WIDTH, int(self.width))
        if self.height is not None:
            self._cap.set(self._cv2.CAP_PROP_FRAME_HEIGHT, int(self.height))
        if self.fps is not None:
            self._cap.set(self._cv2.CAP_PROP_FPS, int(self.fps))

    def read(self) -> Optional[DepthFrame]:
        if self._cap is None:
            raise RuntimeError("OpenCV backend is not started.")

        ok, frame = self._cap.read()
        if not ok:
            return None

        if frame.ndim == 3:
            gray = self._cv2.cvtColor(frame, self._cv2.COLOR_BGR2GRAY)
            depth_m = gray.astype(np.float32) * self.depth_scale
            color_bgr = frame
        else:
            depth_m = frame.astype(np.float32) * self.depth_scale
            color_bgr = None

        return DepthFrame(depth_m=depth_m, color_bgr=color_bgr, timestamp_s=time.time())

    def stop(self) -> None:
        if self._cap is not None:
            self._cap.release()
        self._cap = None

    def metadata(self) -> Dict[str, Any]:
        return {
            "backend": "opencv",
            "source": self.source,
            "width": self.width,
            "height": self.height,
            "fps": self.fps,
            "depth_scale_m": self.depth_scale,
        }

